const d = new Date();
const y = d.getFullYear();
const m = String(d.getMonth()+1).padStart(2,'0');
const day = String(d.getDate()).padStart(2,'0');
const report_date = day+' '+['January','February','March','April','May','June','July','August','September','October','November','December'][d.getMonth()]+' '+y;

// ISO week number
const jan1 = new Date(y,0,1);
const days = Math.floor((d - jan1)/86400000);
const jan1Day = jan1.getDay() || 7;
const weekNum = Math.ceil((days + jan1Day)/7);
const week_number = String(weekNum).padStart(2,'0');

const filename = 'EDGE_CriticalMinerals_Week'+week_number+'_'+y+'-'+m+'-'+day+'.html';

console.log('report_date='+report_date);
console.log('week_number='+week_number);
console.log('year='+y);
console.log('month='+m);
console.log('day='+day);
console.log('filename='+filename);
"
